actions.action:
tk_state: f.tk_state, sla_created_at: f.sla_created_at, sla_note: f.sla_note,
sla_ok: f.sla_ok;

change tk_state value { "new" }
change sla_created_at value { java.time.LocalDateTime.now() }
change sla_ok value { true }
change sla_note value { "Čaká na prevzatie. Lehota sa doplní po triáži." }
changeCaseProperty("title").about { "Nová požiadavka" }

document.function:
{ def caseObj ->
    // Bez tohto by createCase pre sesterskou siet nenasiel - identifikator
    // nesie URI cestu (service_desk/...), takze prefix treba odvodit.
    def pid = caseObj.processIdentifier
    return pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
}

{ def raw ->
    // Hodnota userList pola je UserListFieldValue s userValues, nie zoznam id.
    // Pozor na `u?._id` - `?.` chrani pred null, nie pred chybajucou property,
    // takze na UserFieldValue by to vyhodilo MissingPropertyException a zhodilo
    // celu akciu.
    if (raw == null) return []
    def users = raw.hasProperty("userValues") ? raw.userValues : (raw instanceof List ? raw : null)
    if (!users) return []
    return users.collect { u ->
        if (u == null) return null
        if (u instanceof String) return u
        if (u instanceof Map) return (u["_id"] ?: u["id"])
        return u.hasProperty("id") ? u.id : null
    }.findAll { it != null }.collect { it as String }
}

{ def customerCase ->
    // Nazov aj vsetky aliasy, normalizovane, aby "Netgrif s.r.o." a "netgrif
    // s.r.o." boli ten isty zakaznik.
    def keys = []
    def name = ((customerCase.dataSet["c_name"]?.value ?: "") as String)
    if (name) keys << name
    def alias = ((customerCase.dataSet["c_alias"]?.value ?: "") as String)
    alias.split("\n").each { line -> if (line?.trim()) keys << line }
    return keys.collect { (it as String).trim().toLowerCase() }.findAll { it }
}

{ def caseObj, def orgName ->
    def needle = ((orgName ?: "") as String).trim().toLowerCase()
    if (!needle) return null
    def customers = findCases { it.processIdentifier.eq(net_prefix(caseObj) + "sd_customer") }
    if (!customers) return null
    // Neaktivna zmluva sa neparuje - tiket od byvaleho zakaznika ma skoncit u
    // veduceho, nie u tymu, ktory ho uz neobsluhuje.
    def active = customers.findAll { ((it.dataSet["c_active"]?.value ?: false) as Boolean) }
    return active.find { org_keys(it).contains(needle) }
}

{ def caseObj, def orgName, def tk_agents, def tk_specialists, def tk_org_match,
  def tk_customer_id, def tk_org_name, def tk_worklog ->
    // Toto je miesto, kde sa z textu z eformu stane opravnenie. Kym tu nic
    // nepribehne, tiket vidi iba veduci - to je zamer, nie chyba: tiket od
    // neznamej organizacie nema komu patrit.
    def org = ((orgName ?: "") as String).trim()
    def customer = match_customer(caseObj, org)

    if (!customer) {
        change tk_agents value { [] }
        change tk_specialists value { [] }
        change tk_customer_id value { "" }
        change tk_org_name value { org }
        change tk_org_match value {
            org ? ("Organizácia \"" + org + "\" nie je v registri zákazníkov – tiket vidí iba vedúci.")
                : "Organizácia nie je vyplnená – tiket vidí iba vedúci."
        }
        def log0 = (tk_worklog.value ?: "") as String
        def e0 = java.time.LocalDateTime.now().toString() + "  bez priradenia: " + (org ?: "prázdna organizácia")
        change tk_worklog value { log0 ? log0 + "\n" + e0 : e0 }
        return false
    }

    def agents = user_ids(customer.dataSet["c_agents"]?.value)
    def specialists = user_ids(customer.dataSet["c_specialists"]?.value)
    def name = ((customer.dataSet["c_name"]?.value ?: "") as String)

    change tk_agents value { agents }
    change tk_specialists value { specialists }
    change tk_customer_id value { customer.stringId }
    change tk_org_name value { name }
    change tk_org_match value {
        (agents || specialists)
                ? (name + " – " + (agents.size() + specialists.size()) + " ľudí")
                : (name + " – v registri nemá pridelených ľudí, tiket vidí iba vedúci.")
    }
    def log = (tk_worklog.value ?: "") as String
    def e = java.time.LocalDateTime.now().toString() + "  priradené zákazníkovi: " + name
    change tk_worklog value { log ? log + "\n" + e : e }
    return true
}

{ def priority ->
    // Standard, ked zakaznik nema dohodnute vlastne hodiny.
    def m = ["A": 2, "B": 4, "C": 8]
    return (m[priority as String] ?: 8) as int
}

{ def customerId, def priority ->
    // Hodiny odozvy zo zmluvy zakaznika. SLA appka bez tohto nema zmysel -
    // kazdy zakaznik ma dohodnute ine lehoty, nie jednu maticu pre vsetkych.
    def id = ((customerId ?: "") as String).trim()
    def p = ((priority ?: "") as String).trim().toUpperCase()
    if (!id || !(p in ["A", "B", "C"])) return sla_hours(priority)
    def customer = findCase { it._id.eq(new org.bson.types.ObjectId(id)) }
    if (!customer) return sla_hours(priority)
    def agreed = customer.dataSet["c_sla_" + p.toLowerCase()]?.value
    if (agreed == null) return sla_hours(priority)
    int hours = (agreed as Number).intValue()
    return hours > 0 ? hours : sla_hours(priority)
}

{ def start, def hours ->
    // Pracovny cas Po-Pi 08:00-16:00. Sviatky tato verzia neriesi - patria
    // do kalendara v backendovej sluzbe, nie do Groovy akcie.
    if (start == null) return null
    def cur = start
    int remaining = ((hours as int) * 60)
    int guard = 0
    while (remaining > 0 && guard < 1000) {
        guard++
        if (cur.dayOfWeek.value >= 6) {
            cur = cur.plusDays(1).withHour(8).withMinute(0).withSecond(0).withNano(0)
            continue
        }
        if (cur.hour < 8) {
            cur = cur.withHour(8).withMinute(0).withSecond(0).withNano(0)
            continue
        }
        if (cur.hour >= 16) {
            cur = cur.plusDays(1).withHour(8).withMinute(0).withSecond(0).withNano(0)
            continue
        }
        def endOfDay = cur.withHour(16).withMinute(0).withSecond(0).withNano(0)
        long avail = java.time.temporal.ChronoUnit.MINUTES.between(cur, endOfDay)
        if (avail >= remaining) return cur.plusMinutes(remaining)
        remaining -= (avail as int)
        cur = cur.plusDays(1).withHour(8).withMinute(0).withSecond(0).withNano(0)
    }
    return cur
}

{ def code ->
    def m = ["incident": "Porucha", "service": "Servisný zásah",
             "change": "Žiadosť o zmenu", "access": "Prístup", "question": "Otázka"]
    return m[code as String] ?: "Požiadavka"
}

{ def code ->
    def m = ["analysis": "Analýza", "fix": "Oprava", "test": "Test",
             "deploy": "Nasadenie", "other": "Iné"]
    return m[code as String] ?: "Práca"
}

actions.action:
src_title: f.src_title;

// Bez tohto sa kazdy tiket v zoznamoch vola "Nová požiadavka" az do triaze.
def t = ((src_title.value ?: "") as String).trim()
if (t) {
    changeCaseProperty("title").about { t }
}

src_org: f.src_org, tk_org_override: f.tk_org_override, tk_agents: f.tk_agents,
tk_specialists: f.tk_specialists, tk_org_match: f.tk_org_match,
tk_customer_id: f.tk_customer_id, tk_org_name: f.tk_org_name, tk_worklog: f.tk_worklog;

// Prichadza z eformu cez setData, takze prave tu tiket prvykrat vie, komu
// patri - a az tu dostane niekto ine ako veduci pravo ho vidiet.
apply_customer(useCase, (tk_org_override.value ?: src_org.value), tk_agents,
        tk_specialists, tk_org_match, tk_customer_id, tk_org_name, tk_worklog)

tk_priority: f.tk_priority, src_severity: f.src_severity,
tk_priority_changed: f.tk_priority_changed, tk_priority_reason: f.tk_priority_reason;

// Zmena priority oproti navrhu zakaznika je auditovana udalost a zmluvne
// zavazuje informovat nahlasovatela. Preto sa zapne pole na doduvodnenie
// a stane sa povinnym.
boolean changed = (tk_priority.value as String) != (src_severity.value as String)
change tk_priority_changed value { changed }
make tk_priority_reason, editable on transitions when { return changed }
make tk_priority_reason, required on transitions when { return changed }
make tk_priority_reason, hidden on transitions when { return !changed }

show_submitted: f.show_submitted;

boolean showIt = show_submitted.value == true
make src_title, visible on transitions when { return showIt }
make src_description, visible on transitions when { return showIt }
make src_service, visible on transitions when { return showIt }
make src_severity, visible on transitions when { return showIt }
make src_affects_more, visible on transitions when { return showIt }
make src_steps, visible on transitions when { return showIt }
make src_workaround, visible on transitions when { return showIt }
make src_name, visible on transitions when { return showIt }
make src_email, visible on transitions when { return showIt }
make src_org, visible on transitions when { return showIt }
make src_title, hidden on transitions when { return !showIt }
make src_description, hidden on transitions when { return !showIt }
make src_service, hidden on transitions when { return !showIt }
make src_severity, hidden on transitions when { return !showIt }
make src_affects_more, hidden on transitions when { return !showIt }
make src_steps, hidden on transitions when { return !showIt }
make src_workaround, hidden on transitions when { return !showIt }
make src_name, hidden on transitions when { return !showIt }
make src_email, hidden on transitions when { return !showIt }
make src_org, hidden on transitions when { return !showIt }

new_wi_title: f.new_wi_title, new_wi_type: f.new_wi_type,
new_wi_assignee: f.new_wi_assignee, new_wi_estimate: f.new_wi_estimate,
wi_message: f.wi_message, wi_list: f.wi_list, wi_open: f.wi_open, wi_refs: f.wi_refs,
src_org: f.src_org, src_title: f.src_title, tk_org_name: f.tk_org_name,
tk_worklog: f.tk_worklog;

def title = ((new_wi_title.value ?: "") as String).trim()

// Hodnota userList polia je UserListFieldValue s userValues, nie zoznam id.
// setData aj `change ... value` ale chcu zoznam id - Pattern 20 pouziva
// [loggedUser().id] - takze si ich vytiahneme.
def raw = new_wi_assignee.value
def assigneeIds = []
if (raw != null) {
    def users = raw.hasProperty("userValues") ? raw.userValues : (raw instanceof List ? raw : null)
    if (users) {
        // Pozor: `u?._id` na UserFieldValue vyhodi MissingPropertyException -
        // `?.` chrani pred null, nie pred chybajucou property.
        assigneeIds = users.collect { u ->
            if (u == null) return null
            if (u instanceof String) return u
            if (u instanceof Map) return (u["_id"] ?: u["id"])
            return u.hasProperty("id") ? u.id : null
        }.findAll { it != null }.collect { it as String }
    }
}

if (!title) {
    change wi_message value { "Napíšte, čo treba urobiť." }
} else if (!assigneeIds) {
    change wi_message value { "Vyberte, komu úlohu zadávate." }
} else {
    def child = createCase(net_prefix(useCase) + "sd_work_item")
    def childTask = findTask { it.transitionId.eq("t_define").and(it.caseId.eq(child.stringId)) }

    // Poradie nie je kozmetika: setData spusta set eventy postupne, takze
    // kontext tiketu musi byt zapisany skor, nez wi_title prepise nazov casu,
    // a wi_assignee_id (ktore naplni userList) az uplne nakoniec.
    setData("t_define", child, [
            "wi_ticket_id"   : ["value": useCase.stringId, "type": "text"],
            "wi_ticket_no"   : ["value": (useCase.visualId ?: useCase.stringId), "type": "text"],
            "wi_ticket_title": ["value": (src_title.value ?: ""), "type": "text"],
            "wi_org"         : ["value": (tk_org_name.value ?: src_org.value ?: ""), "type": "text"],
            "wi_type"        : ["value": new_wi_type.value, "type": "enumeration_map"],
            "wi_estimate"    : ["value": new_wi_estimate.value, "type": "number"],
            "wi_title"       : ["value": title, "type": "text"],
            "wi_assignee_id" : ["value": assigneeIds[0], "type": "text"]
    ])


    def refs = (wi_refs.value ?: []) as List
    if (childTask) {
        refs = refs + [childTask.stringId]
        change wi_refs value { refs }
    }

    int open = ((wi_open.value ?: 0) as Number).intValue() + 1
    change wi_open value { open }

    def list = (wi_list.value ?: "") as String
    def line = "• " + title + "  (" + wi_type_label(new_wi_type.value) + ")"
    change wi_list value { list ? list + "\n" + line : line }

    def log = (tk_worklog.value ?: "") as String
    def entry = java.time.LocalDateTime.now().toString() + "  zadaná úloha: " + title
    change tk_worklog value { log ? log + "\n" + entry : entry }

    change new_wi_title value { "" }
    change new_wi_estimate value { null }
    change wi_message value { "Úloha zadaná: " + title }
}

tk_type: f.tk_type, tk_priority: f.tk_priority, tk_priority_reason: f.tk_priority_reason,
tk_priority_changed: f.tk_priority_changed, tk_state: f.tk_state,
src_title: f.src_title, src_email: f.src_email, src_name: f.src_name,
sla_created_at: f.sla_created_at, sla_accepted_at: f.sla_accepted_at,
sla_response_due: f.sla_response_due, sla_ok: f.sla_ok, sla_note: f.sla_note,
tk_customer_id: f.tk_customer_id, tk_worklog: f.tk_worklog;

def now = java.time.LocalDateTime.now()
def created = sla_created_at.value ?: now
def due = business_deadline(created, contract_sla_hours(tk_customer_id.value, tk_priority.value))

change sla_accepted_at value { now }
change sla_response_due value { due }
change tk_state value { "accepted" }

boolean inTime = due == null || !now.isAfter(due)
change sla_ok value { inTime }
change sla_note value {
    inTime ? "Prevzaté v lehote odozvy." : "Lehota odozvy bola prekročená pri prevzatí."
}

changeCaseProperty("title").about {
    type_label(tk_type.value) + " — " + ((src_title.value ?: "bez názvu") as String)
}
changeCaseProperty("color").about { priority_color(tk_priority.value) }

def log = (tk_worklog.value ?: "") as String
def entry = now.toString() + "  triáž: zaradené ako " + type_label(tk_type.value) +
            ", priorita " + (tk_priority.value as String)
if (tk_priority_changed.value == true) {
    entry = entry + " (zmenená, dôvod: " + ((tk_priority_reason.value ?: "") as String) + ")"
}
change tk_worklog value { log ? log + "\n" + entry : entry }

// Informovanie nahlasovatela. Ak mail nie je nakonfigurovany, nesmie to
// zhodit triaz - ticket uz je prevzaty a to je dolezitejsie.
def mail = ((src_email.value ?: "") as String).trim()
if (mail) {
    try {
        def body = "Dobrý deň,\n\nvašu požiadavku sme prevzali.\n" +
                   "Zaradenie: " + type_label(tk_type.value) + "\n" +
                   "Priorita: " + (tk_priority.value as String) + "\n"
        if (tk_priority_changed.value == true) {
            body = body + "Prioritu sme upravili. Dôvod: " +
                   ((tk_priority_reason.value ?: "") as String) + "\n"
        }
        body = body + "\nOzveme sa vám s ďalším postupom."
        sendEmail([mail], "Požiadavka prevzatá", body)
    } catch (Exception e) {
        // Log v akcii nie je zarucene dostupny, takze zlyhanie zapiseme tam,
        // kde ho operator uvidi.
        change tk_worklog value {
            ((tk_worklog.value ?: "") as String) +
            "\nPOZOR: notifikáciu o prevzatí sa nepodarilo poslať (" + e.message + ")"
        }
    }
}

tk_note: f.tk_note, tk_worklog: f.tk_worklog, tk_state: f.tk_state,
sla_pause_from: f.sla_pause_from, sla_pause_minutes: f.sla_pause_minutes;

def now = java.time.LocalDateTime.now()

// Ak sa ticket vracia z cakania na zakaznika, uzavrieme pauzu.
if (sla_pause_from.value != null) {
    long mins = java.time.temporal.ChronoUnit.MINUTES.between(sla_pause_from.value, now)
    change sla_pause_minutes value { ((sla_pause_minutes.value ?: 0) as long) + mins }
    change sla_pause_from value { null }
}

change tk_state value { "working" }

def log = (tk_worklog.value ?: "") as String
def entry = now.toString() + "  postup: " + ((tk_note.value ?: "") as String)
change tk_worklog value { log ? log + "\n" + entry : entry }
change tk_note value { "" }

tk_pending_reason: f.tk_pending_reason, tk_state: f.tk_state,
tk_worklog: f.tk_worklog, sla_pause_from: f.sla_pause_from,
sla_note: f.sla_note, src_email: f.src_email;

def now = java.time.LocalDateTime.now()

change tk_state value { "pending" }
change sla_pause_from value { now }
change sla_note value { "Čaká sa na doplnenie od zákazníka. Lehoty sa nepočítajú." }

def log = (tk_worklog.value ?: "") as String
def entry = now.toString() + "  čaká na zákazníka: " + ((tk_pending_reason.value ?: "") as String)
change tk_worklog value { log ? log + "\n" + entry : entry }

def mail = ((src_email.value ?: "") as String).trim()
if (mail) {
    try {
        sendEmail([mail], "Potrebujeme od vás doplnenie",
            "Dobrý deň,\n\nk vašej požiadavke potrebujeme doplniť:\n\n" +
            ((tk_pending_reason.value ?: "") as String) +
            "\n\nKým nám odpoviete, riešenie je pozastavené.")
    } catch (Exception e) {
        change tk_worklog value {
            ((tk_worklog.value ?: "") as String) +
            "\nPOZOR: výzvu na doplnenie sa nepodarilo poslať (" + e.message + ")"
        }
    }
}

tk_resolution: f.tk_resolution, tk_state: f.tk_state, tk_worklog: f.tk_worklog,
sla_note: f.sla_note, src_email: f.src_email, src_title: f.src_title,
wi_open: f.wi_open;

def now = java.time.LocalDateTime.now()

// Ticket sa da vyriesit aj s otvorenymi ulohami - token uz sa pohol a
// finish sa odtialto nezastavi - ale nech to nezostane neviditelne.
int stillOpen = ((wi_open.value ?: 0) as Number).intValue()
if (stillOpen > 0) {
    def warn = now.toString() + "  POZOR: vyriešené, hoci " + stillOpen + " úloh je otvorených."
    def wlog = (tk_worklog.value ?: "") as String
    change tk_worklog value { wlog ? wlog + "\n" + warn : warn }
}

change tk_state value { "resolved" }
change sla_note value { "Vyriešené " + now.toString() + "." }

def log = (tk_worklog.value ?: "") as String
def entry = now.toString() + "  vyriešené: " + ((tk_resolution.value ?: "") as String)
change tk_worklog value { log ? log + "\n" + entry : entry }

changeCaseProperty("color").about { "green" }

def mail = ((src_email.value ?: "") as String).trim()
if (mail) {
    try {
        sendEmail([mail], "Požiadavka vyriešená: " + ((src_title.value ?: "") as String),
            "Dobrý deň,\n\nvašu požiadavku sme vyriešili.\n\n" +
            ((tk_resolution.value ?: "") as String) +
            "\n\nAk problém pretrváva, odpovedzte na tento e-mail.")
    } catch (Exception e) {
        change tk_worklog value {
            ((tk_worklog.value ?: "") as String) +
            "\nPOZOR: notifikáciu o vyriešení sa nepodarilo poslať (" + e.message + ")"
        }
    }
}
